import * as React from "react"
import { Link } from "gatsby"
import Header from "../../components/Header"
import Seo from "../../components/Seo"
import { ArrowRight, Check } from "../../components/Icons"
import { loadDraft } from "../../lib/site-draft"
import { slugFor } from "../../lib/site-export"
import { RECOVERY_NOTE } from "../../lib/recovery-code"
import { markPurchased } from "../../lib/visit-log"
import * as s from "../../components/Outcome.module.css"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { accessToken } from "../../context/auth"

/**
 * Back from Stripe — and where the site actually goes live.
 * ============================================================================
 *
 * ── THE PAGE ONLY EXISTS IN THE CONTRACTOR'S BROWSER ───────────────────────
 * Nothing was uploaded during the build: the draft is localStorage and the
 * HTML has never left this machine. So this is the first moment the finished
 * page can be handed over, which is why publishing happens HERE rather than in
 * the webhook — the webhook has the payment but not the website.
 *
 * ── IT PUBLISHES ONCE, AND SAYS WHAT HAPPENED ──────────────────────────────
 * The session id from Stripe's redirect is proof of nothing on its own; the
 * publish route looks it up server-side and refuses if it is not paid. This
 * page reports whichever answer comes back, including the unglamorous ones.
 * It never claims a site is live because a payment succeeded — the two are
 * different facts and conflating them is how somebody finds a 404 on the
 * address they just put on a van.
 *
 * ── A REFRESH IS SAFE ──────────────────────────────────────────────────────
 * Re-publishing the same paid session overwrites that contractor's own site
 * and nothing else, so a reloaded tab is harmless rather than a second order.
 */

const SuccessPage = ({ location }) => {
  const [state, setState] = React.useState({ status: "working" })

  React.useEffect(() => {
    const params = new URLSearchParams(location?.search || "")
    const sessionId = params.get("session_id")
    const draft = loadDraft()

    if (!draft || !draft.generated) {
      setState({
        status: "nodraft",
        message:
          "We could not find your website in this browser. If you built it somewhere else, open the builder there and we will pick it back up.",
      })
      return
    }

    if (!sessionId) {
      setState({
        status: "failed",
        message: "This page was opened without a checkout reference, so there is nothing to publish.",
      })
      return
    }

    // The address the contractor actually chose, not one re-derived from the
    // business name — those differ the moment they edit it, and the publish
    // route (rightly) refuses to put a paid order at a different address.
    const slug = draft.slug || slugFor(draft)
    let cancelled = false

    ;(async () => {
      try {
        /* ── PUBLISHED BY AN EDGE FUNCTION — FCS-055, FCS-057 ──────────
           Not /api/publish-site: the site is static on GitHub Pages and that
           route does not exist there, so the old call answered 404 the moment
           anybody actually paid.

           The session goes with it because publishing is not something a
           stranger may do to somebody else's address — the function checks
           the caller owns this subdomain before it writes anything. On an
           anonymous purchase the session is the one create-checkout-session
           minted at the moment of paying, which this browser adopted before
           leaving for Stripe. */
        const token = await accessToken()

        const res = await fetch(apiUrl("publish-site"), {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            apikey: SUPABASE_PUBLISHABLE_KEY,
            Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
          },
          body: JSON.stringify({
            sessionId,
            slug,
            plan: draft.plan,
            businessName: draft.business.name.trim(),
            // The builder's JSON, which is what the site IS — MTC-FCS-032.
            // The function writes it to Storage and the live page reads it
            // back; there is no HTML snapshot any more, because the site is
            // rendered from this file at request time.
            draft,
          }),
        })
        const data = await res.json().catch(() => ({}))
        if (cancelled) return

        if (!res.ok) {
          setState({
            status: "paid-not-live",
            message: data.message || "Your payment went through, but the site could not be published yet.",
          })
          return
        }

        setState({
          status: "live",
          url: data.url,
          subdomain: data.subdomain,
          slug: data.slug,
          // MTC-FCS-015: the server removed sections the payment did not
          // cover. Saying so beats letting them find out from their own site.
          premiumStripped: Boolean(data.premiumStripped),
          templateReset: Boolean(data.templateReset),
          recoveryCode: data.recoveryCode || null,
        })

        // status 2 — MTC-FCS-039. Here rather than at checkout, because a
        // checkout that was started is not a sale.
        markPurchased({ plan: data.plan, site: data.slug })
      } catch {
        if (!cancelled) {
          setState({
            status: "paid-not-live",
            message:
              "Your payment went through, but we could not reach the publishing service. Refresh this page to try again.",
          })
        }
      }
    })()

    return () => {
      cancelled = true
    }
  }, [location])

  const { status } = state

  return (
    <>
      <Header />
      <main className={s.page} data-print="hide">
        <div className="container">
          <div className={`${s.card} ${status === "live" ? s.success : s.neutral}`}>
            <span className={s.mark} aria-hidden="true">
              {status === "live" ? (
                <Check style={{ width: 34, height: 34 }} />
              ) : (
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                  <circle cx="12" cy="12" r="10" />
                  <path d="M12 7v6M12 16.5v.01" />
                </svg>
              )}
            </span>

            {status === "working" && (
              <>
                <h1 className={s.title}>Publishing your website…</h1>
                <p className={s.lead}>
                  Payment received. We are putting your site online now — this takes a few seconds.
                </p>
              </>
            )}

            {status === "live" && (
              <>
                <h1 className={s.title}>Your website is live</h1>
                <p className={s.lead}>
                  Thanks — your site is published and a receipt is on its way to your email.
                </p>

                <p className={s.liveUrl}>
                  <a href={state.url} target="_blank" rel="noreferrer">
                    {state.url}
                  </a>
                </p>

                {state.premiumStripped || state.templateReset ? (
                  <p className={s.smallNote}>
                    {state.premiumStripped && state.templateReset
                      ? "Your Premium sections and page template are not on the published page"
                      : state.premiumStripped
                        ? "Your Premium sections are not on the published page"
                        : "Your Premium page template is not on the published page"}{" "}
                    — this order was paid on the Freemium plan. Nothing extra was charged.
                    Upgrade in the builder and go live again to add them.
                  </p>
                ) : null}

                {state.recoveryCode ? (
                  <div className={s.recovery}>
                    <p className={s.recoveryLabel}>Your recovery code</p>
                    <p className={s.recoveryCode}>{state.recoveryCode}</p>
                    <p className={s.smallNote}>
                      {RECOVERY_NOTE} Write it down now —{" "}
                      <Link to="/help/cannot-log-in">use it here</Link> if you ever get stuck.
                    </p>
                  </div>
                ) : null}

                <ul className={`checks ${s.points}`}>
                  <li>
                    <Check />
                    Edit your content any time from the builder
                  </li>
                  <li>
                    <Check />
                    Your subscription can be cancelled from your receipt email
                  </li>
                  <li>
                    <Check />
                    {state.subdomain} follows once your domain is pointed at us
                  </li>
                </ul>
              </>
            )}

            {(status === "paid-not-live" || status === "failed" || status === "nodraft") && (
              <>
                <h1 className={s.title}>
                  {status === "paid-not-live" ? "Paid — but not live yet" : "We could not publish this"}
                </h1>
                <p className={s.lead}>{state.message}</p>
                {status === "paid-not-live" && (
                  <p className={s.smallNote}>
                    Your payment is safe and your website is still saved in this browser. Nothing
                    needs to be paid again.
                  </p>
                )}
              </>
            )}

            <div className={s.actions}>
              {/* The builder is where you BUILD a site; this page is reached
                  after paying for one, so it goes to the account — FCS-064. */}
              <a href="/account" className="btn btn--lg">
                Go to my dashboard
                <ArrowRight className="btn__arrow" />
              </a>
              <a href="/" className={s.secondary}>
                Return home
              </a>
            </div>
          </div>
        </div>
      </main>
    </>
  )
}

export const Head = () => <Seo title="Your website" />

export default SuccessPage
